/// The paired device behind a request's token, seen now; or the
/// refusal, which says nothing of the host. The bearer is tried
/// first, then this host's cookie (a browser has no bearer). A
/// refusal over this host's own cookie clears it, so a revoked
/// browser drops its token; another host's cookie is never touched.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let cookie_name = self.core.identity().map(remote::token_cookie_name);
    let cookie = cookie_name.as_deref().and_then(|name| {
        request
            .cookies
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, v)| v.as_str())
    });
    let by_token = |token: &str| {
        self.core
            .device_by_token(&remote::token_sha256(token))
            .cloned()
    };
    let device = request
        .bearer
        .as_deref()
        .and_then(&by_token)
        .or_else(|| cookie.and_then(&by_token));
    let Some(device) = device else {
        let (message, cleared) = if request.bearer.is_none() && cookie.is_none() {
            ("pair this device first", false)
        } else {
            ("the token is not known; pair again", cookie.is_some())
        };
        let mut refused = self.refuse(request, 401, "unauthorized", message, false);
        if let (true, Some(name)) = (cleared, &cookie_name) {
            refused.headers.push((
                "Set-Cookie".to_owned(),
                format!("{name}=; Path=/api/v1/; Max-Age=0; Secure; HttpOnly; SameSite=Strict"),
            ));
        }
        return Err(refused);
    };
    self.dispatch_inner(AppAction::DeviceSeen(device.id));
    Ok(device)
}

