/// by `Content-Length`. The reader is left at the next response, so a
/// kept connection can be read again.
#[allow(clippy::type_complexity)] // a status, its headers and a body
fn read_response<R: BufRead>(reader: &mut R) -> std::io::Result<(u16, Vec<(String, String)>, String)> {
    let mut line = String::new();
