/// The page's three files are served before pairing, with the headers
/// the page's policy needs; any other path, or another method on them,
/// is `not_found` as it was.
#[test]
fn the_page_is_served_unpaired_with_its_headers() {
    let mut port = port();
    let csp = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";
    for (path, content_type) in [
        ("/", "text/html; charset=utf-8"),
        ("/app.css", "text/css; charset=utf-8"),
        ("/app.js", "text/javascript; charset=utf-8"),
    ] {
        let (status, headers, body) = call_text(&mut port, "GET", path, None, None, "");
        assert_eq!(status, 200, "{path}");
        assert!(!body.is_empty(), "{path}");
        assert_eq!(header(&headers, "content-type"), Some(content_type), "{path}");
        assert_eq!(header(&headers, "content-security-policy"), Some(csp), "{path}");
        assert_eq!(header(&headers, "cache-control"), Some("no-store"), "{path}");
        assert_eq!(
            header(&headers, "x-content-type-options"),
            Some("nosniff"),
            "{path}"
        );
    }
    for (method, path) in [
        ("GET", "/index.html"),
        ("GET", "/app.js/"),
        ("GET", "/other"),
        ("POST", "/"),
    ] {
        let (status, _, reply) = call_with(&mut port, method, path, None, None, "{}");
        assert_eq!((status, code(&reply)), (404, "not_found"), "{method} {path}");
    }
}

/// The page names only its own files and runs no script the host did
/// not ship: no inline script or style, no address outside the host,
/// and the token never reaches script.
#[test]
fn the_page_references_only_what_the_host_serves() {
    let html = switchboard::web::INDEX_HTML;
    for attr in ["src=\"", "href=\""] {
        for rest in html.split(attr).skip(1) {
            let target = rest.split('"').next().unwrap();
            assert!(
                ["/", "/app.css", "/app.js"].contains(&target),
                "{attr}{target}"
            );
        }
    }
    for part in html.split("<script").skip(1) {
        let body = part.split_once('>').unwrap().1;
        assert!(body.starts_with("</script>"), "a script has a body: {part}");
    }
    assert!(!html.contains("<style"), "no inline style");
    for text in [
        html,
        switchboard::web::APP_CSS,
        switchboard::web::APP_JS,
    ] {
        assert!(!text.contains("style="), "a style attribute");
        assert!(!text.contains("http://") && !text.contains("https://"));
    }
    let js = switchboard::web::APP_JS;
    assert!(!js.contains("Authorization"), "the token never enters script");
    assert!(!js.contains("document.cookie"), "the cookie is never read");
}

/// Open the window with `code` and pair as a browser: returns the
/// cookie it was given, as `name=value`.
fn pair_browser(port: &mut Port, code: &str, device: &str) -> String {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope: Scope::Read,
    });
    let spki = port.remote.state().identity.as_ref().unwrap().spki_sha256.clone();
    let body = serde_json::json!({
        "code": code, "spki_sha256": spki, "device_name": device, "transport": "cookie"
    });
    let (status, headers, reply) =
        call_with(port, "POST", "/api/v1/pair", None, None, &body.to_string());
    assert_eq!(status, 200, "{reply}");
    header(&headers, "set-cookie")
        .expect("a cookie")
        .split("; ")
        .next()
        .unwrap()
        .to_owned()
}

/// A browser pairs from the invite URL: the token comes back as an
/// `HttpOnly` cookie and not in the body, the cookie is the browser's
/// credential, and a revocation clears it. A native client's pairing
/// keeps the token in the body and sets no cookie.
#[test]
fn a_browser_pairs_from_the_invite_and_reads_through_its_cookie() {
    let mut port = port();
    port.app.dispatch(AppAction::OpenPairing {
        code: "ABCD2345".into(),
        scope: Scope::Read,
    });
    let identity = port.remote.state().identity.clone().unwrap();
    let invite =
        switchboard::core::remote::pairing_invite(&identity, "192.168.1.9:43187", "ABCD2345");
    // The phone opens the URL: the secrets are in its fragment, which the
    // host never sees, so the host reads them from what the page sends.
    let fragment = invite.split_once('#').unwrap().1;
    let field = |name: &str| {
        fragment
            .split('&')
            .find_map(|p| p.strip_prefix(&format!("{name}=")))
            .unwrap()
            .to_owned()
    };
    assert_eq!(field("code"), "ABCD2345");
    assert_eq!(field("id"), identity.server_id.to_string());
    let (status, info) = get(&mut port, "/api/v1/info", None);
    assert_eq!(status, 200);
    assert_eq!(field("key"), info["body"]["spki_sha256"].as_str().unwrap());

    let body = serde_json::json!({
        "code": field("code"), "spki_sha256": field("key"),
        "device_name": "Safari on iPhone", "transport": "cookie"
    });
    let (status, headers, reply) =
        call_with(&mut port, "POST", "/api/v1/pair", None, None, &body.to_string());
    assert_eq!(status, 200, "{reply}");
    assert!(reply["body"]["token"].is_null(), "no token in the body: {reply}");
    let name = switchboard::core::remote::token_cookie_name(&identity);
    let set = header(&headers, "set-cookie").expect("a cookie");
    assert!(set.starts_with(&format!("{name}=")), "{set}");
    for attr in ["Path=/api/v1/", "Secure", "HttpOnly", "SameSite=Strict"] {
        assert!(set.split("; ").any(|a| a == attr), "{attr} in {set}");
    }
    let cookie = set.split("; ").next().unwrap().to_owned();

    let (status, _, _) = call_with(&mut port, "GET", "/api/v1/waiting", None, Some(&cookie), "");
    assert_eq!(status, 200, "the cookie reads");
    let device = port.app.core().devices()[0].clone();
    assert_eq!(device.name, "Safari on iPhone");
    assert!(device.last_seen.is_some(), "the read saw the device");
    let sub = subscribe_cookie(&mut port, &cookie);

    // A bearer outranks the cookie; a native pairing answers the token
    // in the body and no cookie.
    port.app.dispatch(AppAction::OpenPairing {
        code: "WXYZ6789".into(),
        scope: Scope::Read,
    });
    let native = serde_json::json!({
        "code": "WXYZ6789", "spki_sha256": field("key"), "device_name": "Pad"
    });
    let (status, headers, reply) =
        call_with(&mut port, "POST", "/api/v1/pair", None, None, &native.to_string());
    assert_eq!(status, 200, "{reply}");
    let bearer = reply["body"]["token"].as_str().unwrap().to_owned();
    assert_eq!(bearer.len(), 43);
    assert!(header(&headers, "set-cookie").is_none(), "no cookie for a client");
    let stale = format!("{name}=not-a-token");
    let (status, _, _) =
        call_with(&mut port, "GET", "/api/v1/waiting", Some(&bearer), Some(&stale), "");
    assert_eq!(status, 200, "a known bearer outranks an unknown cookie");

    // Another host's cookie name is not this host's credential, even
    // with this host's valid token in it; this host's own name is read
    // when both are sent.
    let value = cookie.split_once('=').unwrap().1;
    let other = format!("switchboard_token_{}", uuid::Uuid::new_v4());
    let (status, headers, _) = call_with(
        &mut port,
        "GET",
        "/api/v1/waiting",
        None,
        Some(&format!("{other}={value}")),
        "",
    );
    assert_eq!(status, 401);
    assert!(header(&headers, "set-cookie").is_none(), "another host's cookie is left alone");
    let both = format!("{other}={value}; {cookie}");
    let (status, _, _) = call_with(&mut port, "GET", "/api/v1/waiting", None, Some(&both), "");
    assert_eq!(status, 200, "this host's name is the one read");

    // Revoking the browser closes its socket, and its next request is
    // refused with its cookie cleared.
    let id = port
        .app
        .core()
        .devices()
        .iter()
        .find(|d| d.name == "Safari on iPhone")
        .unwrap()
        .id;
    port.app.dispatch(AppAction::RevokeDevice(id));
    let (status, headers, _) =
        call_with(&mut port, "GET", "/api/v1/waiting", None, Some(&cookie), "");
    assert_eq!(status, 401);
    let clear = header(&headers, "set-cookie").expect("the cookie is cleared");
    assert!(clear.starts_with(&format!("{name}=;")), "{clear}");
    assert!(clear.contains("Max-Age=0"), "{clear}");
    match next_frame(&mut port, &sub, 5) {
        Some(Err(reason)) => assert!(reason.starts_with("closed"), "{reason}"),
        other => panic!("expected the close, got {other:?}"),
    }
}

/// A TLS connection the test keeps across requests, as a browser keeps
/// the sockets of a page load.
type Kept = BufReader<StreamOwned<ClientConnection, TcpStream>>;

fn connect_kept(port: &Port) -> Kept {
    let tcp = TcpStream::connect(port.addr).expect("connect");
    tcp.set_read_timeout(Some(Duration::from_secs(10))).unwrap();
    let conn = ClientConnection::new(
        Arc::clone(&port.client),
        ServerName::try_from("localhost").unwrap(),
    )
    .expect("client");
    let mut s = StreamOwned::new(conn, tcp);
    while s.conn.is_handshaking() {
        s.conn.complete_io(&mut s.sock).expect("handshake");
    }
    BufReader::new(s)
}

/// One `GET` on a kept connection, answered by the app on this thread.
/// The connection comes back for the next request.
#[allow(clippy::type_complexity)] // the connection, a status, its headers and a body
fn get_kept(
    port: &mut Port,
    mut kept: Kept,
    path: &str,
    cookie: Option<&str>,
) -> (Kept, u16, Vec<(String, String)>, String) {
    let cookie = cookie.map(|c| format!("Cookie: {c}\r\n")).unwrap_or_default();
    let request = format!("GET {path} HTTP/1.1\r\nHost: localhost\r\n{cookie}Content-Length: 0\r\n\r\n");
    let client = std::thread::spawn(move || {
        kept.get_mut().write_all(request.as_bytes())?;
        let (status, headers, body) = read_response(&mut kept)?;
        Ok::<_, std::io::Error>((kept, status, headers, body))
    });
    let deadline = std::time::Instant::now() + Duration::from_secs(5);
    while !client.is_finished() {
        assert!(std::time::Instant::now() < deadline, "no reply");
        port.app.serve_pending();
        std::thread::sleep(Duration::from_millis(2));
    }
    client.join().unwrap().expect("a kept request")
}

/// A page load's three connections fit the unauthenticated pool and stay
/// open while a browser that has paired reads and subscribes: the
/// `/waiting` moves its connection to the paired pool, and the socket
/// then opens as a fourth stranger at most.
#[test]
fn a_page_load_fits_the_stranger_pool() {
    let mut port = port();
    let cookie = pair_browser(&mut port, "ABCD2345", "Safari on iPhone");
    // The pairing's own connection must be gone before the pool is counted.
    std::thread::sleep(Duration::from_millis(100));
    let mut held = Vec::new();
    for path in ["/", "/app.css", "/app.js"] {
        let kept = connect_kept(&port);
        let (kept, status, _, _) = get_kept(&mut port, kept, path, None);
        assert_eq!(status, 200, "{path}");
        held.push(kept);
    }
    let fourth = connect_kept(&port);
    let (_fourth, status, _, _) = get_kept(&mut port, fourth, "/api/v1/waiting", Some(&cookie));
    assert_eq!(status, 200, "the cookie moves its connection to the paired pool");
    let _sub = subscribe_cookie(&mut port, &cookie);
    // The three page connections were held open all along.
    let first = held.remove(0);
    let (_, status, _, _) = get_kept(&mut port, first, "/", None);
    assert_eq!(status, 200, "a page connection is still open");
}

